    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    return float(math.log(v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if r is not None and math.isfinite(r) and r > 0 and x > 0:
            total += x * r ** 3
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if z is not None and math.isfinite(z) and z >= 0 and x > 0:
            total += x * z
            weight += x
    if weight <= 0:
        return 0.0
    return float(total / (weight * v))

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(a.get('occupancy', 1.0) or 0.0)) for a in sites]
    nearest = [math.inf for i in range(n)]
    for b in s.get('neighbors', []):
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if occ[j] > 0 and d > 1e-8 and d < nearest[i]:
            nearest[i] = d
    weight = 0.0
    total = 0.0
    square = 0.0
    for i in range(n):
        d = nearest[i]
        if occ[i] > 0 and math.isfinite(d):
            weight += occ[i]
            total += occ[i] * d
            square += occ[i] * d * d
    if weight <= 0 or total <= 0:
        return 0.0
    mean = total / weight
    return float(math.sqrt(max(0.0, square / weight - mean * mean)) / mean)

def feature(s):
