    bonds = s.get('neighbors', [])
    for b in bonds:
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if occ[j] > 0 and d > 1e-8 and d < nearest[i]:
            nearest[i] = d
    coordination = [0.0 for i in range(n)]
    for b in bonds:
        i = b['i']
        d = b['distance_A']
        if d > 1e-8 and d <= 1.25 * nearest[i]:
            coordination[i] += occ[b['j']]
    return float(sum(occ[i] * coordination[i] for i in range(n)) / weight)

