    return float(math.sqrt(max(0.0, variance)) / mean)

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(a.get('occupancy', 1.0) or 0.0)) for a in sites]
    nearest = [math.inf for i in range(n)]
    bonds = s.get('neighbors', [])
    for b in bonds:
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if occ[j] > 0 and d > 1e-8 and d < nearest[i]:
            nearest[i] = d
    inner = [0.0 for i in range(n)]
    outer = [6.0 for i in range(n)]
    for b in bonds:
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if occ[j] > 0 and d > 1e-8:
            if d <= 1.25 * nearest[i]:
                inner[i] = max(inner[i], d)
            else:
                outer[i] = min(outer[i], d)
    total = 0.0
    weight = 0.0
    for i in range(n):
        if inner[i] > 0 and occ[i] > 0:
            total += occ[i] * math.log(max(outer[i], inner[i]) / inner[i])
            weight += occ[i]
    return float(total / weight) if weight > 0 else 0.0
